-- =====================================================================
--  MARKETDATA PERÚ - BASE DE DATOS COMPLETA (esquema + catálogos + datos iniciales)
--  Plataforma de análisis territorial (INEI) y empresarial (SUNAT) - SOA
--  Motor: MySQL 8.0.16+ (también probado en MariaDB 10.11)
--
--  DBeaver / Workbench: abrir este archivo y ejecutarlo COMPLETO como script
--  (DBeaver: Alt + X).  ATENCIÓN: la primera sentencia borra marketdata_db si existe.
--
--  Formato del proyecto:
--    * PK  idNombreTabla INT AUTO_INCREMENT   (multitabla: id_multitabla)
--    * flkactivo tinyint(1) en tablas maestras
--    * Auditoría en todas: usuario_crea, fecha_crea, usuario_modif, fecha_modif
--    * Seguridad: menu -> acceso -> acceso_rol <- rol <- usuario (+ reset_token)
--    * multitabla (codigo_tabla + codigo) con codigo_padre para jerarquías
--      (departamento 001 -> provincia 002 -> distrito 003 = UBIGEO del INEI)
--
--  Tablas de MarketData (capa de persistencia / caché del Capítulo 2):
--    indicador_territorial         caché del Servicio Territorial (INEI)
--    contribuyente                 caché del Servicio Empresarial por RUC (SUNAT)
--    resumen_empresarial(+_sector) caché del Servicio Empresarial por zona (SUNAT)
--    analisis_zona(+_sector)       resultado del Servicio Orquestador "Análisis de zona"
--    log_integracion               bitácora de cada invocación a INEI / SUNAT (pruebas 2.5.4)
-- =====================================================================
SET NAMES utf8mb4;
SET FOREIGN_KEY_CHECKS = 0;

DROP DATABASE IF EXISTS marketdata_db;
CREATE DATABASE marketdata_db CHARACTER SET utf8mb4 COLLATE utf8mb4_spanish_ci;
USE marketdata_db;

-- =====================================================================
-- 1. SEGURIDAD
-- =====================================================================

-- Grupo del menú lateral (Inicio, Análisis de mercado, Integración, Maestros, Seguridad)
CREATE TABLE `menu` (
  `idMenu` int NOT NULL AUTO_INCREMENT,
  `nombre` varchar(45) NOT NULL,
  `descripcion` varchar(45) DEFAULT NULL,
  `orden` int NOT NULL,
  `flkactivo` tinyint(1) NOT NULL,
  `usuario_crea` varchar(50) NOT NULL,
  `fecha_crea` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `usuario_modif` varchar(50) DEFAULT NULL,
  `fecha_modif` timestamp NULL DEFAULT NULL,
  PRIMARY KEY (`idMenu`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_spanish_ci;

CREATE TABLE `multitabla` (
  `id_multitabla` int NOT NULL AUTO_INCREMENT,
  `codigo_tabla` char(3) NOT NULL,
  `nombre_tabla` varchar(100) NOT NULL,
  `codigo` varchar(100) DEFAULT NULL,
  `orden` int DEFAULT NULL,
  `valor` varchar(200) DEFAULT NULL,
  `valor_aux` varchar(200) DEFAULT NULL,
  `valor_aux2` varchar(200) DEFAULT NULL,
  `codigo_padre` varchar(100) DEFAULT NULL COMMENT 'codigo del registro padre (provincia -> departamento, distrito -> provincia)',
  `estado_tabla` char(1) NOT NULL,
  `flkactivo` tinyint(1) NOT NULL,
  `usuario_crea` varchar(50) NOT NULL,
  `fecha_crea` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `usuario_modif` varchar(50) DEFAULT NULL,
  `fecha_modif` timestamp NULL DEFAULT NULL,
  PRIMARY KEY (`id_multitabla`),
  UNIQUE KEY `idx_tabla` (`codigo_tabla`,`codigo`),
  KEY `idx_tabla_padre` (`codigo_tabla`,`codigo_padre`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_spanish_ci;

CREATE TABLE `rol` (
  `idRol` int NOT NULL AUTO_INCREMENT,
  `nombre` varchar(150) DEFAULT NULL,
  `flkactivo` tinyint(1) NOT NULL,
  `usuario_crea` varchar(50) NOT NULL,
  `fecha_crea` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `usuario_modif` varchar(50) DEFAULT NULL,
  `fecha_modif` timestamp NULL DEFAULT NULL,
  PRIMARY KEY (`idRol`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_spanish_ci;

CREATE TABLE `acceso` (
  `idAcceso` int NOT NULL AUTO_INCREMENT,
  `idMenu` int NOT NULL,
  `nombre` varchar(100) NOT NULL,
  `path` varchar(100) NOT NULL,
  `tipo` char(1) NOT NULL DEFAULT 'P' COMMENT 'P = pantalla, A = acción (botón)',
  `orden` int NOT NULL,
  `flkactivo` tinyint(1) NOT NULL,
  `usuario_crea` varchar(50) NOT NULL,
  `fecha_crea` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `usuario_modif` varchar(50) DEFAULT NULL,
  `fecha_modif` timestamp NULL DEFAULT NULL,
  PRIMARY KEY (`idAcceso`),
  KEY `fk_Acceso_Menu1_idx` (`idMenu`),
  CONSTRAINT `fk_Acceso_Menu1` FOREIGN KEY (`idMenu`) REFERENCES `menu` (`idMenu`),
  CONSTRAINT `chk_acceso_tipo` CHECK (`tipo` in ('P','A'))
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_spanish_ci;

CREATE TABLE `acceso_rol` (
  `idAcceso_Rol` int NOT NULL AUTO_INCREMENT,
  `idAcceso` int NOT NULL,
  `idRol` int NOT NULL,
  `usuario_crea` varchar(50) NOT NULL,
  `fecha_crea` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `usuario_modif` varchar(50) DEFAULT NULL,
  `fecha_modif` timestamp NULL DEFAULT NULL,
  PRIMARY KEY (`idAcceso_Rol`),
  UNIQUE KEY `uk_Acceso_Rol` (`idAcceso`,`idRol`),
  KEY `fk_Acceso_Rol_Acceso1_idx` (`idAcceso`),
  KEY `fk_Acceso_Rol_Rol1_idx` (`idRol`),
  CONSTRAINT `fk_Acceso_Rol_Acceso1` FOREIGN KEY (`idAcceso`) REFERENCES `acceso` (`idAcceso`) ON DELETE CASCADE,
  CONSTRAINT `fk_Acceso_Rol_Rol1` FOREIGN KEY (`idRol`) REFERENCES `rol` (`idRol`) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_spanish_ci;

CREATE TABLE `usuario` (
  `idUsuario` int NOT NULL AUTO_INCREMENT,
  `idRol` int NOT NULL,
  `nombres` varchar(150) NOT NULL,
  `apellidos` varchar(150) NOT NULL,
  `usuario` varchar(60) NOT NULL,
  `contrasena` varchar(60) NOT NULL,
  `telefono` varchar(15) DEFAULT NULL,
  `correo` varchar(150) NOT NULL,
  `idTipoDocumento` int DEFAULT NULL COMMENT 'multitabla 004',
  `dni` varchar(15) DEFAULT NULL COMMENT 'número del documento (DNI, CE o pasaporte)',
  `foto` longblob,
  `flkactivo` tinyint(1) NOT NULL,
  `usuario_crea` varchar(50) NOT NULL,
  `fecha_crea` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `usuario_modif` varchar(50) DEFAULT NULL,
  `fecha_modif` timestamp NULL DEFAULT NULL,
  PRIMARY KEY (`idUsuario`),
  UNIQUE KEY `usuario_UNIQUE` (`usuario`),
  KEY `fk_Usuario_Rol1_idx` (`idRol`),
  KEY `fk_Usuario_TipoDocumento1` (`idTipoDocumento`),
  CONSTRAINT `fk_Usuario_Rol1` FOREIGN KEY (`idRol`) REFERENCES `rol` (`idRol`),
  CONSTRAINT `fk_Usuario_TipoDocumento1` FOREIGN KEY (`idTipoDocumento`) REFERENCES `multitabla` (`id_multitabla`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_spanish_ci;

CREATE TABLE `reset_token` (
  `idResetToken` bigint NOT NULL AUTO_INCREMENT,
  `token` varchar(300) NOT NULL,
  `expiracion` datetime NOT NULL,
  `flkactivo` tinyint(1) NOT NULL DEFAULT '1',
  `idUsuario` int NOT NULL,
  `usuario_crea` varchar(50) NOT NULL,
  `fecha_crea` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `usuario_modif` varchar(50) DEFAULT NULL,
  `fecha_modif` timestamp NULL DEFAULT NULL,
  PRIMARY KEY (`idResetToken`),
  UNIQUE KEY `token_UNIQUE` (`token`),
  KEY `fk_ResetToken_Usuario1_idx` (`idUsuario`),
  CONSTRAINT `fk_ResetToken_Usuario1` FOREIGN KEY (`idUsuario`) REFERENCES `usuario` (`idUsuario`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_spanish_ci;

-- =====================================================================
-- 2. MARKETDATA - SERVICIO TERRITORIAL (INEI)
--    Una fila por UBIGEO consultado. vigente_hasta = criterio de vigencia de la caché
--    (parámetro CACHE_VIGENCIA_HORAS). Si INEI no responde se usa la última fila aunque esté vencida.
-- =====================================================================
CREATE TABLE `indicador_territorial` (
  `idIndicadorTerritorial` int NOT NULL AUTO_INCREMENT,
  `ubigeo` varchar(6) NOT NULL COMMENT '2 = departamento, 4 = provincia, 6 = distrito',
  `nivel` varchar(12) NOT NULL COMMENT 'DEPARTAMENTO | PROVINCIA | DISTRITO',
  `departamento` varchar(100) DEFAULT NULL,
  `provincia` varchar(100) DEFAULT NULL,
  `distrito` varchar(100) DEFAULT NULL,
  `poblacion_total` int DEFAULT NULL,
  `poblacion_urbana` int DEFAULT NULL,
  `poblacion_rural` int DEFAULT NULL,
  `poblacion_hombres` int DEFAULT NULL,
  `poblacion_mujeres` int DEFAULT NULL,
  `hogares` int DEFAULT NULL,
  `superficie_km2` decimal(12,2) DEFAULT NULL,
  `densidad_hab_km2` decimal(12,2) DEFAULT NULL,
  `edad_promedio` decimal(5,2) DEFAULT NULL,
  `tasa_pobreza` decimal(5,2) DEFAULT NULL COMMENT '% de población en situación de pobreza',
  `pea` int DEFAULT NULL COMMENT 'población económicamente activa',
  `anio_referencia` smallint DEFAULT NULL,
  `fuente` varchar(80) NOT NULL DEFAULT 'INEI',
  `fecha_consulta` datetime NOT NULL,
  `vigente_hasta` datetime NOT NULL,
  `usuario_crea` varchar(50) NOT NULL,
  `fecha_crea` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `usuario_modif` varchar(50) DEFAULT NULL,
  `fecha_modif` timestamp NULL DEFAULT NULL,
  PRIMARY KEY (`idIndicadorTerritorial`),
  UNIQUE KEY `uk_indicador_ubigeo` (`ubigeo`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_spanish_ci;

-- =====================================================================
-- 3. MARKETDATA - SERVICIO EMPRESARIAL (SUNAT)
-- =====================================================================

-- Contribuyente consultado por RUC (o recibido como muestra de una zona)
CREATE TABLE `contribuyente` (
  `idContribuyente` int NOT NULL AUTO_INCREMENT,
  `ruc` char(11) NOT NULL,
  `razon_social` varchar(200) NOT NULL,
  `tipo_contribuyente` varchar(100) DEFAULT NULL,
  `nombre_comercial` varchar(200) DEFAULT NULL,
  `estado` varchar(40) DEFAULT NULL COMMENT 'multitabla 034: ACTIVO, BAJA DE OFICIO...',
  `condicion` varchar(40) DEFAULT NULL COMMENT 'multitabla 035: HABIDO, NO HABIDO...',
  `ciiu` varchar(6) DEFAULT NULL,
  `actividad_economica` varchar(250) DEFAULT NULL,
  `seccion_ciiu` char(1) DEFAULT NULL COMMENT 'multitabla 033',
  `ubigeo` varchar(6) DEFAULT NULL,
  `direccion` varchar(250) DEFAULT NULL,
  `fecha_inscripcion` date DEFAULT NULL,
  `fuente` varchar(80) NOT NULL DEFAULT 'SUNAT',
  `fecha_consulta` datetime NOT NULL,
  `vigente_hasta` datetime NOT NULL,
  `usuario_crea` varchar(50) NOT NULL,
  `fecha_crea` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `usuario_modif` varchar(50) DEFAULT NULL,
  `fecha_modif` timestamp NULL DEFAULT NULL,
  PRIMARY KEY (`idContribuyente`),
  UNIQUE KEY `uk_contribuyente_ruc` (`ruc`),
  KEY `idx_contribuyente_ubigeo` (`ubigeo`, `seccion_ciiu`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_spanish_ci;

-- Concentración de empresas en una zona (respuesta SUNAT por UBIGEO)
CREATE TABLE `resumen_empresarial` (
  `idResumenEmpresarial` int NOT NULL AUTO_INCREMENT,
  `ubigeo` varchar(6) NOT NULL,
  `total_empresas` int NOT NULL DEFAULT 0,
  `empresas_activas` int NOT NULL DEFAULT 0,
  `empresas_habidas` int NOT NULL DEFAULT 0,
  `empresas_baja` int NOT NULL DEFAULT 0,
  `fuente` varchar(80) NOT NULL DEFAULT 'SUNAT',
  `fecha_consulta` datetime NOT NULL,
  `vigente_hasta` datetime NOT NULL,
  `usuario_crea` varchar(50) NOT NULL,
  `fecha_crea` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `usuario_modif` varchar(50) DEFAULT NULL,
  `fecha_modif` timestamp NULL DEFAULT NULL,
  PRIMARY KEY (`idResumenEmpresarial`),
  UNIQUE KEY `uk_resumen_ubigeo` (`ubigeo`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_spanish_ci;

CREATE TABLE `resumen_empresarial_sector` (
  `idResumenEmpresarialSector` int NOT NULL AUTO_INCREMENT,
  `idResumenEmpresarial` int NOT NULL,
  `seccion_ciiu` char(1) NOT NULL COMMENT 'multitabla 033',
  `cantidad` int NOT NULL DEFAULT 0,
  `activas` int NOT NULL DEFAULT 0,
  `usuario_crea` varchar(50) NOT NULL,
  `fecha_crea` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `usuario_modif` varchar(50) DEFAULT NULL,
  `fecha_modif` timestamp NULL DEFAULT NULL,
  PRIMARY KEY (`idResumenEmpresarialSector`),
  UNIQUE KEY `uk_resumen_sector` (`idResumenEmpresarial`, `seccion_ciiu`),
  CONSTRAINT `fk_ResumenSector_Resumen1` FOREIGN KEY (`idResumenEmpresarial`) REFERENCES `resumen_empresarial` (`idResumenEmpresarial`) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_spanish_ci;

-- =====================================================================
-- 4. MARKETDATA - SERVICIO ORQUESTADOR "ANÁLISIS DE ZONA"
--    Histórico de cada análisis: permite comparar zonas sin volver a llamar a INEI / SUNAT.
-- =====================================================================
CREATE TABLE `analisis_zona` (
  `idAnalisisZona` int NOT NULL AUTO_INCREMENT,
  `ubigeo` varchar(6) NOT NULL,
  `nivel` varchar(12) NOT NULL,
  `nombre_zona` varchar(250) NOT NULL COMMENT 'DISTRITO, PROVINCIA, DEPARTAMENTO',
  `seccion_interes` char(1) DEFAULT NULL COMMENT 'rubro del negocio que se quiere abrir (multitabla 033)',
  `poblacion_total` int DEFAULT NULL,
  `densidad_hab_km2` decimal(12,2) DEFAULT NULL,
  `tasa_pobreza` decimal(5,2) DEFAULT NULL,
  `total_empresas` int DEFAULT NULL,
  `empresas_activas` int DEFAULT NULL,
  `empresas_rubro` int DEFAULT NULL COMMENT 'empresas activas del rubro de interés',
  `empresas_por_mil` decimal(10,2) DEFAULT NULL COMMENT 'empresas activas por cada 1000 habitantes',
  `habitantes_por_empresa` decimal(12,2) DEFAULT NULL,
  `sector_predominante` char(1) DEFAULT NULL,
  `indice_demanda` decimal(5,2) DEFAULT NULL,
  `indice_competencia` decimal(5,2) DEFAULT NULL,
  `indice_poder_adquisitivo` decimal(5,2) DEFAULT NULL,
  `indice_atractivo` decimal(5,2) DEFAULT NULL COMMENT '0 a 100',
  `nivel_atractivo` varchar(10) DEFAULT NULL COMMENT 'multitabla 036: ALTO, MEDIO, BAJO',
  `estado` varchar(10) NOT NULL COMMENT 'COMPLETO | PARCIAL | FALLIDO',
  `origen_territorial` varchar(15) DEFAULT NULL COMMENT 'INEI | CACHE | CACHE_VENCIDA | ERROR',
  `origen_empresarial` varchar(15) DEFAULT NULL,
  `tiempo_territorial_ms` int DEFAULT NULL,
  `tiempo_empresarial_ms` int DEFAULT NULL,
  `tiempo_total_ms` int DEFAULT NULL,
  `observacion` varchar(500) DEFAULT NULL,
  `usuario_crea` varchar(50) NOT NULL,
  `fecha_crea` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `usuario_modif` varchar(50) DEFAULT NULL,
  `fecha_modif` timestamp NULL DEFAULT NULL,
  PRIMARY KEY (`idAnalisisZona`),
  KEY `idx_analisis_ubigeo` (`ubigeo`, `fecha_crea`),
  KEY `idx_analisis_fecha` (`fecha_crea`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_spanish_ci;

CREATE TABLE `analisis_zona_sector` (
  `idAnalisisZonaSector` int NOT NULL AUTO_INCREMENT,
  `idAnalisisZona` int NOT NULL,
  `seccion_ciiu` char(1) NOT NULL,
  `cantidad` int NOT NULL DEFAULT 0,
  `porcentaje` decimal(5,2) NOT NULL DEFAULT 0,
  `por_mil_habitantes` decimal(10,2) DEFAULT NULL,
  `usuario_crea` varchar(50) NOT NULL,
  `fecha_crea` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `usuario_modif` varchar(50) DEFAULT NULL,
  `fecha_modif` timestamp NULL DEFAULT NULL,
  PRIMARY KEY (`idAnalisisZonaSector`),
  UNIQUE KEY `uk_analisis_sector` (`idAnalisisZona`, `seccion_ciiu`),
  CONSTRAINT `fk_AnalisisSector_Analisis1` FOREIGN KEY (`idAnalisisZona`) REFERENCES `analisis_zona` (`idAnalisisZona`) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_spanish_ci;

-- =====================================================================
-- 5. BITÁCORA DE INTEGRACIÓN (cada llamada a INEI / SUNAT, con reintentos y tiempos)
-- =====================================================================
CREATE TABLE `log_integracion` (
  `idLogIntegracion` bigint NOT NULL AUTO_INCREMENT,
  `servicio` varchar(20) NOT NULL COMMENT 'INEI | SUNAT',
  `operacion` varchar(60) NOT NULL,
  `protocolo` varchar(10) NOT NULL COMMENT 'REST | SOAP',
  `url` varchar(300) DEFAULT NULL,
  `parametro` varchar(100) DEFAULT NULL,
  `estado_http` int DEFAULT NULL,
  `intentos` tinyint NOT NULL DEFAULT 1,
  `exito` tinyint(1) NOT NULL,
  `tiempo_ms` int DEFAULT NULL,
  `mensaje` varchar(500) DEFAULT NULL,
  `usuario_crea` varchar(50) NOT NULL,
  `fecha_crea` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `usuario_modif` varchar(50) DEFAULT NULL,
  `fecha_modif` timestamp NULL DEFAULT NULL,
  PRIMARY KEY (`idLogIntegracion`),
  KEY `idx_log_fecha` (`fecha_crea`),
  KEY `idx_log_servicio` (`servicio`, `exito`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_spanish_ci;

-- =====================================================================
-- 6. VISTA DE UBIGEO (distrito con su provincia y departamento)
-- =====================================================================
CREATE OR REPLACE VIEW `v_ubigeo` AS
SELECT d.codigo AS ubigeo,
       dep.valor AS departamento,
       p.valor   AS provincia,
       d.valor   AS distrito,
       dep.codigo AS codigo_departamento,
       p.codigo   AS codigo_provincia
  FROM multitabla d
  JOIN multitabla p   ON p.codigo_tabla = '002' AND p.codigo = d.codigo_padre
  JOIN multitabla dep ON dep.codigo_tabla = '001' AND dep.codigo = p.codigo_padre
 WHERE d.codigo_tabla = '003';

