-- ADMINISTRADOR: todo
INSERT INTO acceso_rol (idAcceso, idRol, usuario_crea)
SELECT a.idAcceso, 1, 'admin' FROM acceso a;

-- ANALISTA: inicio, análisis de mercado (con forzar) y ver la bitácora
INSERT INTO acceso_rol (idAcceso, idRol, usuario_crea)
SELECT a.idAcceso, 2, 'admin' FROM acceso a
 WHERE a.idMenu IN (1, 2) OR a.path = '/pages/marketdata/bitacora.html';

